return ['domain'=>'zinn-cache','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ta_IN','project-id-version'=>'zinn-cache','pot-creation-date'=>'2026-09-02T07:33:02+00:00','po-revision-date'=>'2026-09-02T07:33:02+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache'=>'Zinn® Cache','https://zinndigital.com/wordpress-plugins/zinn-cache'=>'https://zinndigital.com/wordpress-plugins/zinn-cache','For sites hosted with Zinn Digital®. Controls the page cache your Zinn® server already provides — smart auto-purge on content change, remote purge from your Zinn® dashboard, a Redis object-cache toggle, safe WordPress/WooCommerce exclusions, and one-click admin login. This is a cache controller, not a cache engine. Hosting elsewhere? Install Zinn® Cache Engine instead.'=>'Zinn Digital® இல் ஹோஸ்ட் செய்யப்பட்ட தளங்களுக்கு. உங்கள் Zinn® சேவையகம் ஏற்கனவே வழங்கும் பக்க தற்காலிக சேமிப்பைக் கட்டுப்படுத்துகிறது — உள்ளடக்க மாற்றத்தின் போது ஸ்மார்ட் ஆட்டோ-பர்ஜ், உங்கள் Zinn® டாஷ்போர்டிலிருந்து ரிமோட் பர்ஜ், Redis ஆப்ஜெக்ட்-கேச் டோகிள், பாதுகாப்பான WordPress/WooCommerce விலக்குகள் மற்றும் ஒரே கிளிக்கில் நிர்வாகி உள்நுழைவு. இது ஒரு தற்காலிக சேமிப்புக் கட்டுப்பாட்டாளர், தற்காலிக சேமிப்பு இயந்திரம் அல்ல. வேறு எங்கு ஹோஸ்ட் செய்கிறீர்கள்? அதற்கு பதிலாக Zinn® Cache Engine ஐ நிறுவவும்.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','You are not allowed to purge the cache.'=>'கேச்சை நீக்க உங்களுக்கு அனுமதி இல்லை.','Cache purge requested.'=>'கேச் நீக்கம் கோரப்பட்டது.','Zinn® Cache: another object-cache drop-in is installed, so the Redis object cache is not managed by this plugin.'=>'Zinn® கேச்: மற்றொரு ஆப்ஜெக்ட்-கேச் டிராப்-இன் நிறுவப்பட்டுள்ளது, எனவே Redis ஆப்ஜெக்ட் கேச் இந்த செருகுநிரலால் நிர்வகிக்கப்படவில்லை.','Full-page cache (LiteSpeed)'=>'முழுப்-பக்கக் கேச் (LiteSpeed)','Enable LSCache control'=>'LSCache கட்டுப்பாட்டை இயக்கு','Send LiteSpeed cache-control and tag headers on cacheable pages.'=>'கேச் செய்யக்கூடிய பக்கங்களில் LiteSpeed கேச்-கட்டுப்பாடு மற்றும் டேக் ஹெடர்களை அனுப்பு.','Public cache lifetime (seconds)'=>'பொது கேச் ஆயுட்காலம் (வினாடிகள்)','Object cache (Redis)'=>'ஆப்ஜெக்ட் கேச் (Redis)','Enable Redis object cache'=>'Redis ஆப்ஜெக்ட் கேச்சை இயக்கு','Install the Redis object-cache drop-in (requires the phpredis extension).'=>'Redis ஆப்ஜெக்ட்-கேச் drop-in ஐ நிறுவு (phpredis நீட்டிப்பு தேவை).','Redis host'=>'Redis ஹோஸ்ட்','Redis port'=>'Redis போர்ட்','Redis database'=>'Redis தரவுத்தளம்','Redis key prefix'=>'Redis கீ முன்னொட்டு','Automatic purging'=>'தானியங்கி நீக்கம்','Smart auto-purge'=>'ஸ்மார்ட் தானியங்கி நீக்கம்','Purge affected pages automatically when content changes.'=>'உள்ளடக்கம் மாறும்போது பாதிக்கப்பட்ட பக்கங்களைத் தானாக நீக்கு.','Purge on updates'=>'புதுப்பிப்புகளின்போது நீக்கு','Purge everything after core, plugin, or theme updates.'=>'கோர், செருகுநிரல் அல்லது தீம் புதுப்பிப்புகளுக்குப் பிறகு அனைத்தையும் நீக்கு.','Cache exclusions'=>'கேச் விலக்குகள்','Sensible WordPress and WooCommerce defaults are always applied (cart, checkout, my-account, logged-in and session pages are never cached). Add extra rules below, one per line.'=>'நியாயமான WordPress மற்றும் WooCommerce இயல்புநிலைகள் எப்போதும் பயன்படுத்தப்படுகின்றன (கார்ட், செக்அவுட், my-account, உள்நுழைந்த மற்றும் அமர்வுப் பக்கங்கள் ஒருபோதும் கேச் செய்யப்படுவதில்லை). கீழே கூடுதல் விதிகளைச் சேர்க்கவும், ஒரு வரிக்கு ஒன்று.','Exclude URL paths (prefix match)'=>'URL பாதைகளை விலக்கு (முன்னொட்டுப் பொருத்தம்)','Exclude query keys'=>'வினவல் கீகளை விலக்கு','Exclude cookie name prefixes'=>'குக்கீ பெயர் முன்னொட்டுகளை விலக்கு','Maintenance'=>'பராமரிப்பு','Purge everything now'=>'இப்போதே அனைத்தையும் நீக்கு','detected'=>'கண்டறியப்பட்டது','not detected'=>'கண்டறியப்படவில்லை','phpredis extension missing'=>'phpredis நீட்டிப்பு இல்லை','active'=>'செயலில் உள்ளது','inactive'=>'செயலில் இல்லை','LiteSpeed cache:'=>'LiteSpeed கேச்:','Redis object cache:'=>'Redis ஆப்ஜெக்ட் கேச்:','The Redis PHP extension (phpredis) is not available on this server, so the object cache cannot be enabled.'=>'இந்த சர்வரில் Redis PHP நீட்டிப்பு (phpredis) கிடைக்கவில்லை, எனவே ஆப்ஜெக்ட் கேச்சை இயக்க முடியாது.','Another object-cache drop-in is already installed. Remove it before enabling the Zinn® object cache.'=>'மற்றொரு ஆப்ஜெக்ட்-கேச் டிராப்-இன் ஏற்கனவே நிறுவப்பட்டுள்ளது. Zinn® ஆப்ஜெக்ட் கேச்-ஐ இயக்குவதற்கு முன்பு அதை அகற்றவும்.','Could not write the Redis connection configuration file.'=>'Redis இணைப்பு உள்ளமைவு கோப்பை எழுத முடியவில்லை.','The bundled object-cache drop-in could not be read.'=>'தொகுக்கப்பட்ட ஆப்ஜெக்ட்-கேச் drop-in ஐப் படிக்க முடியவில்லை.','Could not install the object-cache drop-in into wp-content.'=>'ஆப்ஜெக்ட்-கேச் drop-in ஐ wp-content இல் நிறுவ முடியவில்லை.','Could not remove the object-cache drop-in.'=>'ஆப்ஜெக்ட்-கேச் drop-in ஐ அகற்ற முடியவில்லை.','The WordPress filesystem is not writable, so the object-cache drop-in could not be managed.'=>'WordPress கோப்பு அமைப்பு எழுதக்கூடியதாக இல்லை, எனவே ஆப்ஜெக்ட்-கேச் drop-in ஐ நிர்வகிக்க முடியவில்லை.','This one-click login link is not valid any more. Links expire after a couple of minutes and can only be used once — open your site from the Zinn® dashboard again to get a fresh one.'=>'இந்த ஒரு கிளிக் உள்நுழைவு இணைப்பு இனி செல்லுபடியாகாது. இணைப்புகள் சில நிமிடங்களுக்குப் பிறகு காலாவதியாகும் மற்றும் ஒருமுறை மட்டுமே பயன்படுத்த முடியும் — புதிய இணைப்பைப் பெற, Zinn® டாஷ்போர்டிலிருந்து உங்கள் தளத்தை மீண்டும் திறக்கவும்.','See the Zinn Digital® release notes.'=>'Zinn Digital® வெளியீட்டு குறிப்புகளைப் பார்க்கவும்.','The downloaded update failed its integrity check and was not installed.'=>'பதிவிறக்கம் செய்யப்பட்ட புதுப்பிப்பு அதன் நம்பகத்தன்மை சரிபார்ப்பில் தோல்வியடைந்ததால் நிறுவப்படவில்லை.','%s — guides and services'=>'%s — வழிகாட்டிகளும் சேவைகளும்','User guides'=>'பயனர் வழிகாட்டிகள்','Read the %s user guide'=>'%s பயனர் வழிகாட்டியைப் படிக்கவும்','Hide this'=>'மறை','Zinn® hosting for WordPress'=>'WordPressக்கான Zinn® ஹோஸ்டிங்','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, தினசரி காப்புப்பிரதிகள், இலவச இடம்பெயர்வு மற்றும் ஒன்றுக்கு மேற்பட்ட தளங்களை இயக்குபவர்களுக்காக உருவாக்கப்பட்ட கட்டுப்பாட்டுப் பலகம்.','The Zinn® marketplace'=>'The Zinn® அங்காடி','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'நிறுவப்பட்ட தளங்கள், டொமைன்கள் மற்றும் இணைப்பு இடங்களை வாங்கவும் விற்கவும், இரு தரப்பினரும் திருப்தி அடையும் வரை பணம் பாதுகாப்பாகப் பிடிக்கப்படும்.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — இதைத் தொழிலாகச் செய்பவர்களைப் பணியமர்த்துங்கள்','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'எங்களின் உலகளாவிய ஃப்ரீலான்ஸ் சந்தை: எழுத்தாளர்கள், வடிவமைப்பாளர்கள், டெவலப்பர்கள் மற்றும் எஸ்சிஓ நிபுணர்களிடமிருந்து 10,000 க்கும் மேற்பட்ட ரெடிமேட் சேவைகளை உலாவுக, அல்லது ஒரு திட்டத்தை இடுகையிட்டு அவர்களை ஏலம் விடச் செய்யுங்கள்.']];